// src/components/Controls.js

import React from 'react';
import { useTranslation } from 'react-i18next';
import './Controls.css';

const Controls = ({
  provinces,
  selectedProvinces,
  onChangeProvinces,
  foodTypes,
  selectedFoodType,
  onChangeFoodType,
  dateRange,
  onChangeDateRange,
  currencies,
  selectedCurrency,
  onChangeCurrency,
